mapper.select:
SELECT a.id, a.actor_type, a.actor_id, coalesce(u.display_name, u.email) AS actor_name, a.action,
       a.target_type, a.target_id, a.details::text AS details, host(a.ip) AS ip, a.created_at
FROM audit_logs a
LEFT JOIN staff_users u ON a.actor_type = 'STAFF' AND u.id = a.actor_id

    a.action = #{action}
    AND a.actor_id = #{actorId}
    AND a.created_at >= #{from}
    AND a.created_at < #{to}
    AND a.created_at < #{before}

ORDER BY a.created_at DESC, a.id DESC
LIMIT #{limit}
